(function(){
  function C(n){ try { return Java.loadClass(n); } catch (e) { return Packages.java.lang.Class.forName(n); } }
  if (typeof AutoJS === 'undefined') { throw new Error('端点: server 侧 AutoJS 全局缺失（通道未注入）'); }
  var ps = AutoJS.players();
  if (ps === null || ps.length < 1) { throw new Error('端点: 世界内没有玩家'); }
  var p = ps[0];
  var Cur = C('com.merlinkitsune.astral_dice.economy.StarCoinCurrency');
  var Eco = C('com.merlinkitsune.starengine.economy.StarEngineEconomy');
  var enabled = Cur.isWalletEnabled();
  var available = Eco.isAvailable();
  var b0 = Number(Eco.getBalance(p));
  var seedOk = Eco.setBalance(p, b0);
  var depOk = Eco.deposit(p, 10);
  var b1 = Number(Eco.getBalance(p));
  var wdOk = Eco.withdraw(p, 4);
  var b2 = Number(Eco.getBalance(p));
  var poorOk = Eco.withdraw(p, b2 + 1);
  var b3 = Number(Eco.getBalance(p));
  Eco.setBalance(p, b0);
  var restored = Number(Eco.getBalance(p)) === b0;
  return { enabled: enabled, available: available, seedOk: seedOk, depOk: depOk, wdOk: wdOk,
           poorOk: poorOk, restored: restored,
           deltaDep: b1 - b0, deltaWd: b2 - b1, deltaPoor: b3 - b2 };
})()
